1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <title>Pulsing Circle</title>
7	  <style>
8	    * {
9	      margin: 0;
10	      padding: 0;
11	      box-sizing: border-box;
12	    }
13	    body {
14	      width: 100vw;
15	      height: 100vh;
16	      display: flex;
17	      justify-content: center;
18	      align-items: center;
19	      background: radial-gradient(circle at center, #1a1a2e 0%, #0d0d17 100%);
20	      overflow: hidden;
21	    }
22	    svg {
23	      width: min(400px, 80vmin);
24	      height: min(400px, 80vmin);
25	      overflow: visible;
26	    }
27	    .core {
28	      animation: pulse 2.5s ease-in-out infinite;
29	      transform-origin: 200px 200px;
30	      filter: url(#glow);
31	    }
32	    .ring {
33	      fill: none;
34	      stroke: #8ec5ff;
35	      stroke-width: 2;
36	      transform-origin: 200px 200px;
37	      animation: ripple 2.5s ease-out infinite;
38	    }
39	    .ring--delay-1 {
40	      animation-delay: 0.83s;
41	    }
42	    .ring--delay-2 {
43	      animation-delay: 1.66s;
44	    }
45	    @keyframes pulse {
46	      0%, 100% {
47	        transform: scale(1);
48	        opacity: 0.9;
49	      }
50	      50% {
51	        transform: scale(1.05);
52	        opacity: 1;
53	      }
54	    }
55	    @keyframes ripple {
56	      0% {
57	        transform: scale(1);
58	        opacity: 0.6;
59	      }
60	      100% {
61	        transform: scale(1.35);
62	        opacity: 0;
63	      }
64	    }
65	    @media (prefers-reduced-motion: reduce) {
66	      .core, .ring {
67	        animation: none;
68	      }
69	    }
70	  </style>
71	</head>
72	<body>
73	  <svg id="ae683f770" viewBox="0 0 400 400" role="img" aria-label="Pulsing blue circle animation">
74	    <defs>
75	      <radialGradient id="circleGradient" cx="35%" cy="35%" r="65%">
76	        <stop offset="0%" stop-color="#8ec5ff"/>
77	        <stop offset="55%" stop-color="#4a7dd9"/>
78	        <stop offset="100%" stop-color="#1f3a75"/>
79	      </radialGradient>
80	      <filter id="glow" x="-50%" y="-50%" width="200%" height="200%">
81	        <feGaussianBlur in="SourceGraphic" stdDeviation="8" result="blur"/>
82	        <feMerge>
83	          <feMergeNode in="blur"/>
84	          <feMergeNode in="SourceGraphic"/>
85	        </feMerge>
86	      </filter>
87	    </defs>
88	    <circle class="ring" cx="200" cy="200" r="180"/>
89	    <circle class="ring ring--delay-1" cx="200" cy="200" r="180"/>
90	    <circle class="ring ring--delay-2" cx="200" cy="200" r="180"/>
91	    <circle class="core" cx="200" cy="200" r="180" fill="url(#circleGradient)"/>
92	  </svg>
93	</body>
94	</html>
